package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PathVariable;

/**
 * Adds a DRAFT claim dated the sheet's today, with an empty note, for the person of that name or alias (name
 * compared as the person form compares it), first adding the person with grade A when no one on
 * the sheet has that name. One change: a refused claim leaves no new person behind.
 */
public class SaveQuickClaim {

    private static final String GRADE = "A";

    public void save(@PathVariable("sheetId") String sheetId, @Val ValidQuickClaim request, People people, Claims claims,
            Sheets sheets, Periods periods, Audit audit, @Val RollupFigures before, Rollup rollup,
            net.officefloor.hq.app.setting.Settings settings, ClaimLog log, net.officefloor.hq.app.holiday.Holidays holidays,
            ObjectResponse<ResponseEntity<ClaimResponse>> response) throws InvalidClaimException {
        LocalDate date = settings.claimDate(sheetId);
        Person person = people.findByName(sheetId, request.name());
        // Refuse before anything is written: the claim's period goes by the due-by it would be fixed with.
        LocalDate dueBy = holidays.dueBy(sheetId, date, person != null
                ? settings.termsFor(sheetId, person.getTerms(), person.gradeOn(date), date)
                : settings.termsFor(sheetId, GRADE, date));
        if (periods.isClosed(sheetId, dueBy)) {
            throw new InvalidClaimException("No claim can be added inside a closed period");
        }
        if (person != null && !person.allowsClaimOn(date)) {
            throw new InvalidClaimException("No claim can be dated after the person's retirement date");
        }
        RollupFigures beforeClaim = before;
        if (person == null) {
            person = people.add(sheetId, request.name(), GRADE);
            audit.recordOnCommit("PERSON_ADDED sheet=" + sheetId + " by=" + request.user()
                    + " name=" + person.getName() + " grade=" + person.getGrade());
            rollup.recordChanges(sheetId, request.user(), before);
            beforeClaim = rollup.figures(sheetId);
        }
        Claim claim = claims.add(sheetId, person.getId(), request.amount(), date, "", dueBy);
        log.record(claim, person, request.user());
        audit.recordOnCommit(ClaimAudit.line("CLAIM_ADDED", request.user(), person, claim, claim.getNumber()));
        LateEntry.mark(claim, person, request.user(), claims, periods, audit);
        rollup.recordChanges(sheetId, request.user(), beforeClaim);
        response.send(new ResponseEntity<>(ClaimResponse.from(claim), HttpStatus.CREATED));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/**
 * Adds the pasted claims as DRAFTs, in order, each audited as CLAIM_ADDED. Every line is checked
 * against the sheet first (the person is on the sheet, by name or alias, matched as names are compared; the date is not
 * inside a closed period nor after the person's retirement), so one refused line writes nothing.
 */
public class SavePasteClaims {
    public void save(@PathVariable("sheetId") String sheetId, @Val ValidPasteClaims request, People people, Claims claims,
            Sheets sheets, Periods periods, Audit audit, @Val RollupFigures before, Rollup rollup, Settings settings,
            ClaimLog log, net.officefloor.hq.app.holiday.Holidays holidays, ObjectResponse<PasteClaimsResponse> response) throws InvalidClaimException {
        LocalDate today = settings.claimDate(sheetId);
        List<Person> persons = new ArrayList<>();
        List<LocalDate> dates = new ArrayList<>();
        int number = 0;
        for (ValidPasteClaims.Line line : request.lines()) {
            number++;
            Person person = people.findByName(sheetId, line.name());
            if (person == null) {
                throw new InvalidClaimException("Claim " + number + ": no one on the sheet is named " + line.name());
            }
            LocalDate date = line.claim().date() != null ? line.claim().date() : today;
            LocalDate dueBy = holidays.dueBy(sheetId, date, settings.termsFor(sheetId, person.getTerms(), person.gradeOn(date), date));
            if (periods.isClosed(sheetId, dueBy)) {
                throw new InvalidClaimException("Claim " + number + ": no claim can be added inside a closed period");
            }
            if (!person.allowsClaimOn(date)) {
                throw new InvalidClaimException("Claim " + number + ": no claim can be dated after the person's retirement date");
            }
            try {
                ValidateClaim.checkRef(line.claim().ref(), sheetId, null, claims);
            } catch (InvalidClaimException e) {
                throw new InvalidClaimException("Claim " + number + ": " + e.getMessage());
            }
            persons.add(person);
            dates.add(date);
        }
        for (int i = 0; i < request.lines().size(); i++) {
            ValidClaim valid = request.lines().get(i).claim();
            Person person = persons.get(i);
            LocalDate date = dates.get(i);
            Claim claim = claims.add(sheetId, person.getId(), valid.amount(), date, valid.note(), null,
                    holidays.dueBy(sheetId, date, settings.termsFor(sheetId, person.getTerms(), person.gradeOn(date), date)), valid.ref());
            log.record(claim, person, request.user());
            audit.recordOnCommit(ClaimAudit.added(request.user(), person, claim));
            LateEntry.mark(claim, person, request.user(), claims, periods, audit);
        }
        rollup.recordChanges(sheetId, request.user(), before);
        response.send(new PasteClaimsResponse(request.lines().size()));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimNumbering;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

/**
 * Transfers the person to another sheet (a steward only; never a retired person, never to this sheet, never onto an
 * archived sheet, nor when their name, an alias or their contact is already on the other sheet). They arrive with
 * every grade they were given, their terms, contact and aliases, and their claims (status, dates, notes, tags,
 * settled figures and logs kept, listed in the same order); each claim that had a number takes the other sheet's
 * next, in the order the claims were opened (by the sheet's today when opened, then the order added). Figures a
 * statement bound and the claims' references are not carried; the statement count starts at 0. They leave this
 * sheet entirely: patron links, pool memberships, holds, statements and watches are dropped.
 */
public class TransferPerson {
    public void transfer(@Val TransferRequest request, @Val Person person, People people, Claims claims,
            ClaimNumbering numbering, Sheets sheets, Settings settings, Audit audit, @Val RollupFigures before,
            Rollup rollup) throws InvalidPersonException {
        String sheetId = person.getSheetId();
        String to = request.toSheet();
        if (!Settings.STEWARD.equals(settings.role(sheetId, request.user()))) {
            throw new InvalidPersonException("Only a steward can transfer people");
        }
        if (person.getRetiredFrom() != null) {
            throw new InvalidPersonException("A retired person cannot be transferred");
        }
        if (sheets.archived(to)) {
            throw new InvalidPersonException("The sheet transferred to is archived");
        }
        List<String> names = new ArrayList<>();
        names.add(person.getName());
        names.addAll(person.getAliases());
        for (String name : names) {
            if (people.nameTaken(to, name, null)) {
                throw new InvalidPersonException("The name " + name + " is already on the other sheet");
            }
        }
        if (person.getContact() != null && !person.getContact().isBlank() && people.contactTaken(to, person.getContact(), null)) {
            throw new InvalidPersonException("The contact is already on the other sheet");
        }
        RollupFigures toBefore = rollup.figures(to);

        Person arrived = people.transferIn(person, to);
        // Claims in the order they are listed (oldest listed first), so they keep their order.
        List<Claim> moved = new ArrayList<>(claims.ofPerson(sheetId, person.getId()));
        java.util.Collections.reverse(moved);
