  holds: HoldFrom[];
  patrons: string[];
  patronIds: string[];
  grades: GradeFrom[];
  /** The person's own terms in days; "" for none. */
  terms: string;
  /** The person's contact, trimmed and lower-cased; "" for none. */
  contact: string;
  /** The person's aliases, sorted as names are compared. */
  aliases: string[];
